evel\":\"intro\",\"primary_topic\":\"pilot wave theory\",\"categories\":[\"Quantum physics\"],\"tags\":[\"bohmian mechanics\",\"quantum mechanics\",\"interpretations of quantum mechanics\",\"de broglie-bohm\",\"physics\"],\"quote\":\"I love this series, Looking Glass Universe, on the subject [0,1].\",\"recommenders\":3,\"score\":3.5},{\"vid\":\"r2CbbBLVaPk\",\"title\":\"The User is Drunk\",\"channel\":\"squareweave\",\"summary\":\"A short talk by Will Dayble of Squareweave arguing that you should design software as if the user were drunk: distracted, impaired in attention and vision, and prone to misreading. It is a user experience talk built around that framing.\",\"why_hn\":\"HN users recommend it as a memorable, short way to build empathy for users' confusing mistakes and to design for distraction.\",\"content_type\":\"talk\",\"level\":\"general\",\"primary_topic\":\"user experience design\",\"categories\":[\"UX & UI design\"],\"tags\":[\"ux\",\"user interfaces\",\"usability\",\"design empathy\",\"web apps\"],\"quote\":\"There's a great short talk called \\\"the user is drunk\",\"recommenders\":4,\"score\":3.5},{\"vid\":\"r6Rp-uo6HmI\",\"title\":\"Why Snow and Confetti Ruin YouTube Video Quality\",\"channel\":\"Tom Scott\",\"summary\":\"Tom Scott explains why confetti and snow wreck video quality, using interframe compression and bitrate. He demonstrates it live by changing the quality on screen.\",\"why_hn\":\"Used as the clearest short demonstration of why noisy, high-motion content is hard for video compression.\",\"content_type\":\"explainer\",\"level\":\"general\",\"primary_topic\":\"video compression\",\"categories\":[\"Information theory & signal processing\",\"Audio & video engineering\"],\"tags\":[\"video compression\",\"bitrate\",\"interframe\",\"youtube quality\",\"tom scott\"],\"quote\":\"Tom Scott has a good video where turns up and down the quality live so you can see it in a single video\",\"recommenders\":3,\"score\":3.5},{\"vid\":\"rCMh7srOqvw\",